/**
 * @file Accounts.tsx
 * @description Staff accounts (admins only): add a person, change a role,
 * turn an account off or on, and reset a forgotten password. A new or reset
 * password is generated by the server and shown here once, to pass on in
 * person; the person changes it under My account.
 */

import { useId, useState, type FormEvent } from 'react';
import StaffLayout from '../../components/StaffLayout/StaffLayout';
import RequestState, { errorMessage } from '../../components/RequestState/RequestState';
import Button from '../../components/Button/Button';
import Notice from '../../components/Notice/Notice';
import { api, ApiError } from '../../api/client';
import useRequest from '../../api/useRequest';
import { useI18n } from '../../i18n/I18nProvider';
import { useAuth } from '../../staff/auth';
import { dateTime } from '../../staff/time';
import type { StaffAccount, StaffRole, TemporaryPassword } from '../../api/types';
import styles from '../../staff/staff.module.css';

const ROLES: StaffRole[] = ['officer', 'supervisor', 'admin'];

function Accounts() {
  const { t } = useI18n();
  const { user } = useAuth();
  const accounts = useRequest(api.staffAccounts, { immediate: true, args: [] });
  const [issued, setIssued] = useState<TemporaryPassword | null>(null);
  const [rowError, setRowError] = useState<string | null>(null);
  const [busyRow, setBusyRow] = useState<string | null>(null);

  const change = async (account: StaffAccount, work: () => Promise<unknown>) => {
    setBusyRow(account.username);
    setRowError(null);
    try {
      await work();
      await accounts.retry();
    } catch (err) {
      setRowError(errorMessage(t, err));
    } finally {
      setBusyRow(null);
    }
  };

  const reset = (account: StaffAccount) => {
    if (!window.confirm(t('staff.accounts.resetConfirm', { name: account.full_name }))) return;
    change(account, async () => setIssued(await api.resetStaffPassword(account.username)));
  };

  return (
    <StaffLayout title={t('staff.nav.accounts')} lede={t('staff.accounts.lede')}>
      <div className={styles.stack}>
        {issued && <IssuedPassword issued={issued} onDone={() => setIssued(null)} />}

        <AddAccount
          onCreated={(result) => {
            setIssued(result);
            accounts.retry();
          }}
        />

        <section className="panel" aria-labelledby="accounts-list">
          <h2 id="accounts-list" className="panel-title">
            {t('staff.accounts.listTitle')}
          </h2>
          {rowError && (
            <Notice tone="error" live>
              {rowError}
            </Notice>
          )}
          {accounts.status === 'success' ? (
            <div className={styles.tableWrap}>
              <table className={styles.table}>
                <thead>
                  <tr>
                    <th scope="col">{t('staff.accounts.col.person')}</th>
                    <th scope="col">{t('staff.accounts.col.role')}</th>
                    <th scope="col">{t('staff.accounts.col.lastSignIn')}</th>
                    <th scope="col">{t('staff.col.status')}</th>
                    <th scope="col">
                      <span className="visually-hidden">{t('staff.accounts.col.actions')}</span>
                    </th>
                  </tr>
                </thead>
                <tbody>
                  {accounts.data.map((a) => {
                    const self = a.username === user?.username;
                    const busy = busyRow === a.username;
                    return (
                      <tr key={a.username} className={a.is_active ? undefined : styles.inactive}>
                        <td>
                          {a.full_name}
                          {self && <span className={styles.you}> {t('staff.accounts.you')}</span>}
                          <span className={`${styles.cellSub} code`}>{a.username}</span>
                        </td>
                        <td data-label={t('staff.accounts.col.role')}>
                          <select
                            className={styles.select}
                            value={a.role}
                            disabled={self || busy}
                            aria-label={t('staff.accounts.roleFor', { name: a.full_name })}
                            onChange={(e) =>
                              change(a, () => api.updateStaffAccount(a.username, { role: e.target.value as StaffRole }))
                            }
                          >
                            {ROLES.map((r) => (
                              <option key={r} value={r}>
                                {t(`staff.role.${r}`)}
                              </option>
                            ))}
                          </select>
                        </td>
                        <td data-label={t('staff.accounts.col.lastSignIn')} className="code">
                          {a.last_sign_in ? dateTime(a.last_sign_in) : t('staff.accounts.never')}
                        </td>
                        <td data-label={t('staff.col.status')}>
                          {a.is_active ? t('staff.accounts.active') : t('staff.accounts.off')}
                        </td>
                        <td data-label={t('staff.accounts.col.actions')}>
                          <span className={styles.rowActions}>
                            <Button variant="text" disabled={busy} onClick={() => reset(a)}>
                              {t('staff.accounts.reset')}
                            </Button>
                            {!self && (
                              <Button
                                variant="text"
                                disabled={busy}
                                onClick={() => change(a, () => api.updateStaffAccount(a.username, { is_active: !a.is_active }))}
                              >
                                {a.is_active ? t('staff.accounts.turnOff') : t('staff.accounts.turnOn')}
                              </Button>
                            )}
                          </span>
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>
          ) : (
            <RequestState status={accounts.status} error={accounts.error} onRetry={accounts.retry} />
          )}
        </section>
      </div>
    </StaffLayout>
  );
}

function AddAccount({ onCreated }: { onCreated: (result: TemporaryPassword) => void }) {
  const { t } = useI18n();
  const [name, setName] = useState('');
  const [username, setUsername] = useState('');
  const [role, setRole] = useState<StaffRole>('officer');
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const nameId = useId();
  const userId = useId();
  const roleId = useId();

  const submit = async (e: FormEvent) => {
    e.preventDefault();
    const clean = username.trim().toLowerCase();
    if (!name.trim() || !/^[a-z0-9._-]{3,32}$/.test(clean)) {
      setError(t('staff.accounts.badInput'));
      return;
    }
    setBusy(true);
    setError(null);
    try {
      onCreated(await api.createStaffAccount({ username: clean, full_name: name.trim(), role }));
      setName('');
      setUsername('');
      setRole('officer');
    } catch (err) {
      setError(err instanceof ApiError && err.kind === 'conflict' ? t('staff.accounts.taken') : errorMessage(t, err));
    } finally {
      setBusy(false);
    }
  };

  return (
    <section className="panel" aria-labelledby="accounts-add">
      <h2 id="accounts-add" className="panel-title">
        {t('staff.accounts.addTitle')}
      </h2>
      {error && (
        <Notice tone="error" live>
          {error}
        </Notice>
      )}
      <form className={styles.filters} onSubmit={submit} noValidate>
        <div className={styles.filter}>
          <label htmlFor={nameId}>{t('staff.accounts.name')}</label>
          <input id={nameId} className={styles.search} value={name} onChange={(e) => setName(e.target.value)} autoComplete="off" />
        </div>
        <div className={styles.filter}>
          <label htmlFor={userId}>{t('signin.username')}</label>
          <input
            id={userId}
            className={styles.search}
            value={username}
            onChange={(e) => setUsername(e.target.value)}
            autoComplete="off"
            autoCapitalize="none"
            spellCheck={false}
            aria-describedby="accounts-username-hint"
          />
        </div>
        <div className={styles.filter}>
          <label htmlFor={roleId}>{t('staff.accounts.col.role')}</label>
          <select id={roleId} className={styles.select} value={role} onChange={(e) => setRole(e.target.value as StaffRole)}>
            {ROLES.map((r) => (
              <option key={r} value={r}>
                {t(`staff.role.${r}`)}
              </option>
            ))}
          </select>
        </div>
        <Button type="submit" loading={busy}>
          {t('staff.accounts.add')}
        </Button>
      </form>
      <p id="accounts-username-hint" className="text-small text-secondary">
        {t('staff.accounts.usernameHint')}
      </p>
      <p className="text-small text-secondary">{t('staff.accounts.roleHelp')}</p>
    </section>
  );
}

function IssuedPassword({ issued, onDone }: { issued: TemporaryPassword; onDone: () => void }) {
  const { t } = useI18n();
  const [copied, setCopied] = useState(false);
  const copy = async () => {
    try {
      await navigator.clipboard.writeText(issued.temporary_password);
      setCopied(true);
    } catch {
      // No clipboard (http, old browser): the password is on screen to read out.
    }
  };
  return (
    <div className="panel">
      <Notice
        tone="done"
        live
        title={t('staff.accounts.issuedTitle', { name: issued.account.full_name })}
        actions={
          <>
            <Button variant="secondary" onClick={copy}>
              {copied ? t('staff.accounts.copied') : t('staff.accounts.copy')}
            </Button>
            <Button variant="text" onClick={onDone}>
              {t('staff.accounts.done')}
            </Button>
          </>
        }
      >
        <p>
          {t('staff.accounts.issuedUser')} <strong className="code">{issued.account.username}</strong>
          <br />
          {t('staff.accounts.issuedPassword')} <strong className={`code ${styles.secret}`}>{issued.temporary_password}</strong>
        </p>
        <p className="text-small">{t('staff.accounts.issuedHelp')}</p>
      </Notice>
    </div>
  );
}

export default Accounts;
